  question:'以下哪些物品應該放在急救箱內？哪些物品不應該放在急救箱內？把它們分類。\nA. 消毒膠布。\nB. 膠水。\nC. 剪刀。\nD. 消毒藥水。\nE. 打火機。\nF. 電筒。',
