然而，珊瑚礁正面臨嚴重的威脅。全球暖化導致海水溫度上升，使珊瑚出現「白化」現象——珊瑚因壓力而排出體內的共生藻類，失去顏色，最終死亡。此外，海洋酸化、污染和過度捕撈也嚴重破壞了珊瑚礁生態系統。

