// ============ STATE ============
let STATE = {
  playerName: '',
  level: 1,
  xp: 0,
  coins: 0,
  badges: [],
  loginStreak: 1,
  lastLoginDate: '',
  currentModule: null,
  currentQType: null,
  stats: {
    totalAnswered: 0,
    totalCorrect: 0,
    maxStreak: 0,
    currentStreak: 0,
    byModule: {},
    today: { answered: 0, correct: 0, xp: 0, coins: 0, date: '' },
    lastPerfect: false,
    wrongRetried: 0
  },
  wrongBank: [],
  customQuestions: [],
  settings: { musicOn: true, volume: 0.4 },
  parentUnlocked: false,
  dailyLog: []
};

const XP_PER_LEVEL = 100;

// ============ STORAGE ============
const Store = {
  save() { try { localStorage.setItem('hinson_v2', JSON.stringify(STATE)); } catch(e){} },
  load() {
    try {
      const d = localStorage.getItem('hinson_v2');
      if (d) STATE = Object.assign(STATE, JSON.parse(d));
    } catch(e) {}
  }
};

// ============ AUDIO MANAGER ============
const AudioMgr = {
  ctx: null, gainNode: null, bgInterval: null, musicOn: true,
  sfxBuffers: {},

  init() {
    this.musicOn = STATE.settings.musicOn;
    document.getElementById('volSlider').value = STATE.settings.volume;
  },

  getCtx() {
    if (!this.ctx) {
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      this.gainNode = this.ctx.createGain();
      this.gainNode.gain.value = STATE.settings.volume;
      this.gainNode.connect(this.ctx.destination);
    }
    return this.ctx;
  },

  playTone(freq, type='sine', dur=0.15, vol=0.3, delay=0) {
    try {
      const ctx = this.getCtx();
      const osc = ctx.createOscillator();
      const g = ctx.createGain();
      osc.connect(g); g.connect(this.gainNode);
      osc.type = type; osc.frequency.value = freq;
      const t = ctx.currentTime + delay;
      g.gain.setValueAtTime(vol, t);
      g.gain.exponentialRampToValueAtTime(0.001, t + dur);
      osc.start(t); osc.stop(t + dur + 0.01);
    } catch(e) {}
  },

  correct() {
    this.playTone(523, 'sine', 0.1, 0.4);
    this.playTone(659, 'sine', 0.1, 0.4, 0.1);
    this.playTone(784, 'sine', 0.15, 0.4, 0.2);
  },

  wrong() {
    this.playTone(200, 'square', 0.15, 0.3);
    this.playTone(150, 'square', 0.15, 0.3, 0.15);
  },

  click() { this.playTone(440, 'sine', 0.05, 0.2); },

  levelUp() {
    [523,659,784,1047].forEach((f,i) => this.playTone(f,'sine',0.2,0.4,i*0.12));
  },

  coin() { this.playTone(880,'sine',0.08,0.3); this.playTone(1100,'sine',0.08,0.3,0.08); },

  startBgMusic() {
    if (!this.musicOn) return;
    const melody = [262,294,330,349,392,440,494,523,392,330,294,262,0,330,392,440,349,330,294,0];
    let idx = 0;
    if (this.bgInterval) clearInterval(this.bgInterval);
    this.bgInterval = setInterval(() => {
      if (!this.musicOn) return;
      const f = melody[idx % melody.length];
      if (f > 0) this.playTone(f, 'triangle', 0.35, 0.08);
      idx++;
    }, 400);
  },

  stopBgMusic() {
    if (this.bgInterval) { clearInterval(this.bgInterval); this.bgInterval = null; }
  },

  toggleMusic() {
    this.musicOn = !this.musicOn;
    STATE.settings.musicOn = this.musicOn;
    Store.save();
    document.getElementById('musicToggle').textContent = this.musicOn ? '🎵' : '🔇';
    if (this.musicOn) this.startBgMusic();
    else this.stopBgMusic();
  },

  setVolume(v) {
    STATE.settings.volume = parseFloat(v);
    if (this.gainNode) this.gainNode.gain.value = parseFloat(v);
    Store.save();
  },

  speak(text) {
    if (!window.speechSynthesis) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'zh-HK';
    u.rate = 0.85;
    const voices = window.speechSynthesis.getVoices();
    const hk = voices.find(v => v.lang === 'zh-HK') || voices.find(v => v.lang.startsWith('zh'));
    if (hk) u.voice = hk;
    window.speechSynthesis.speak(u);
  },

  speakEl(id) {
    const el = document.getElementById(id);
    if (el) this.speak(el.innerText || el.textContent);
  },

  speakQuestion() { this.speakEl('qText'); }
};

// ============ PARTICLE SYSTEM ============
const Particles = {
  canvas: null, ctx: null, particles: [],
  init() {
    this.canvas = document.getElementById('bgCanvas');
    this.ctx = this.canvas.getContext('2d');
    this.resize();
    window.addEventListener('resize', () => this.resize());
    this.initStars();
    requestAnimationFrame(() => this.loop());
  },
  resize() {
    this.canvas.width = window.innerWidth;
    this.canvas.height = window.innerHeight;
    this.initStars();
  },
  stars: [],
  initStars() {
    this.stars = Array.from({length: 120}, () => ({
      x: Math.random() * this.canvas.width,
      y: Math.random() * this.canvas.height,
      r: Math.random() * 1.5 + 0.3,
      a: Math.random(),
      da: (Math.random() - 0.5) * 0.01
    }));
  },
  burst(x, y, color='#d4af37') {
    for (let i = 0; i < 20; i++) {
      const angle = (Math.PI * 2 / 20) * i;
      const speed = Math.random() * 4 + 2;
      this.particles.push({
        x, y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1, decay: Math.random() * 0.02 + 0.015,
        r: Math.random() * 4 + 2, color
      });
    }
  },
  loop() {
    const c = this.ctx;
    c.clearRect(0, 0, this.canvas.width, this.canvas.height);

    // Stars
    this.stars.forEach(s => {
      s.a += s.da;
      if (s.a < 0 || s.a > 1) s.da *= -1;
      c.beginPath();
      c.arc(s.x, s.y, s.r, 0, Math.PI * 2);
      c.fillStyle = `rgba(255,255,255,${s.a})`;
      c.fill();
    });

    // Particles
    this.particles = this.particles.filter(p => p.life > 0);
    this.particles.forEach(p => {
      p.x += p.vx; p.y += p.vy;
      p.vy += 0.1; p.life -= p.decay;
      c.beginPath();
      c.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      c.fillStyle = p.color + Math.floor(p.life * 255).toString(16).padStart(2,'0');
      c.fill();
    });

    requestAnimationFrame(() => this.loop());
  }
};

// ============ REWARD SYSTEM ============
const Rewards = {
  addXP(amount) {
    const prevLevel = STATE.level;
    STATE.xp += amount;
    STATE.stats.today.xp += amount;
    while (STATE.xp >= XP_PER_LEVEL) {
      STATE.xp -= XP_PER_LEVEL;
      STATE.level++;
    }
    if (STATE.level > prevLevel) {
      AudioMgr.levelUp();
      document.getElementById('lvlupNum').textContent = STATE.level;
      App.openModal('modal-levelup');
      Particles.burst(window.innerWidth/2, window.innerHeight/3, '#ffd700');
    }
    App.updateStatsBar();
  },

  addCoins(amount) {
    STATE.coins += amount;
    STATE.stats.today.coins += amount;
    AudioMgr.coin();
    App.updateStatsBar();
  },

  checkBadges() {
    BADGES.forEach(b => {
      if (!STATE.badges.includes(b.id) && b.check(STATE)) {
        STATE.badges.push(b.id);
        App.toast('🎖️ 獲得勳章：' + b.name);
        Particles.burst(window.innerWidth/2, window.innerHeight/2, '#d4af37');
      }
    });
  }
};

// ============ QUIZ ENGINE ============
const QuizEngine = {
  questions: [], idx: 0, answers: [], timer: null, timeLeft: 0, totalTime: 30,
  sessionCorrect: 0, earnedXP: 0, earnedCoins: 0, newBadges: [],
  currentUserAnswer: null, submitted: false,
  classify_state: {},

  start(questions) {
    this.questions = questions;
    this.idx = 0; this.answers = [];
    this.sessionCorrect = 0; this.earnedXP = 0; this.earnedCoins = 0;
    this.newBadges = []; this.submitted = false;
    this.sessionStartTime = Date.now();
    App.showScreen('screen-quiz');
    this.renderQuestion();
  },

  renderQuestion() {
    if (this.idx >= this.questions.length) { this.finish(); return; }
    const q = this.questions[this.idx];
    this.currentUserAnswer = null; this.submitted = false;
    this.classify_state = {};

    document.getElementById('qModBadge').textContent = q.module + ' ' + App.moduleName(q.module);
    document.getElementById('qTypeBadge').textContent = App.typeName(q.type);
    document.getElementById('qTypeLbl').textContent = App.typeName(q.type);
    document.getElementById('qCounter').textContent = (this.idx+1) + '/' + this.questions.length;
    const pct = (this.idx / this.questions.length * 100).toFixed(0);
    document.getElementById('qProgFill').style.width = pct + '%';

    // Reading passage
    const passEl = document.getElementById('readPassage');
    if (q.passage) {
      passEl.style.display = 'block';
      document.getElementById('passageBody').textContent = q.passage;
    } else { passEl.style.display = 'none'; }

    // Question image (for scenario questions with images)
    let qImgEl = document.getElementById('qImage');
    if (!qImgEl) {
      qImgEl = document.createElement('img');
      qImgEl.id = 'qImage';
      qImgEl.className = 'q-image';
      const qTextEl = document.getElementById('qText');
      qTextEl.parentNode.insertBefore(qImgEl, qTextEl);
    }
    if (q.image) {
      qImgEl.src = q.image;
      qImgEl.style.display = 'block';
    } else {
      qImgEl.style.display = 'none';
    }

    document.getElementById('qText').textContent = q.question;
    document.getElementById('feedbackArea').style.display = 'none';
    document.getElementById('quizNavRow').style.display = 'flex';

    this.renderAnswerArea(q);
    const timerSec = q.type === 'analysis' ? 90
      : q.type === 'short' ? 60
      : (q.type === 'match' || q.type === 'order') ? (q.left ? q.left.length * 15 : 60)
      : q.type === 'scenario' ? 120
      : q.type === 'classify' ? 60
      : 30;
    this.startTimer(timerSec);
  },

  renderAnswerArea(q) {
    const area = document.getElementById('answerArea');
    area.innerHTML = '';

    if (q.type === 'mc') {
      if (q.multi) {
        // Multi-select hint
        const hint = document.createElement('div');
        hint.style.cssText = 'font-size:12px;color:#00e5e5;margin-bottom:8px;';
        hint.textContent = '✦ 此題可選多個答案，請選出所有正確選項';
        area.appendChild(hint);
        this.currentUserAnswer = [];
      }
      const opts = document.createElement('div');
      opts.className = 'mc-options';
      const letters = ['A','B','C','D'];
      q.options.forEach((opt, i) => {
        const btn = document.createElement('button');
        btn.className = 'mc-option';
        btn.innerHTML = `<span class="mc-option-letter">${letters[i]}</span><span>${opt}</span>`;
        btn.onclick = () => {
          if (q.multi) {
            btn.classList.toggle('selected');
            const sel = this.currentUserAnswer || [];
            const idx = sel.indexOf(i);
            if (idx === -1) sel.push(i); else sel.splice(idx, 1);
            this.currentUserAnswer = sel;
          } else {
            document.querySelectorAll('.mc-option').forEach(b => b.classList.remove('selected'));
            btn.classList.add('selected');
            this.currentUserAnswer = i;
          }
          AudioMgr.click();
        };
        opts.appendChild(btn);
      });
      area.appendChild(opts);

    } else if (q.type === 'fill' || q.type === 'short' || q.type === 'scenario' || q.type === 'analysis') {
      const rows = q.type === 'analysis' ? 6 : q.type === 'scenario' ? 5 : 3;
      const ta = document.createElement('textarea');
      ta.className = 'quiz-textarea';
      ta.rows = rows;
      ta.placeholder = q.type === 'fill' ? '請填入答案⋯' : '請在此輸入你的答案⋯';
      ta.oninput = () => { this.currentUserAnswer = ta.value.trim(); };
      area.appendChild(ta);

      // Hint button — show model answer on demand
      this.hintUsed = false;
      const hintWrap = document.createElement('div');
      hintWrap.className = 'hint-wrap';

      const hintBtn = document.createElement('button');
      hintBtn.className = 'pixel-btn grey hint-btn';
      hintBtn.innerHTML = '💡 唔識？睇參考答案';
      hintBtn.onclick = () => {
        const box = document.getElementById('hintAnswerBox');
        if (box.style.display === 'none') {
          box.style.display = 'block';
          hintBtn.innerHTML = '🙈 收起答案';
          if (!this.hintUsed) {
            this.hintUsed = true;
            App.toast('已顯示參考答案，此題不計分');
          }
        } else {
          box.style.display = 'none';
          hintBtn.innerHTML = '💡 唔識？睇參考答案';
        }
        AudioMgr.click();
      };
      hintWrap.appendChild(hintBtn);

      const hintBox = document.createElement('div');
      hintBox.id = 'hintAnswerBox';
      hintBox.className = 'hint-answer-box';
      hintBox.style.display = 'none';
      const answerText = q.answer || '';
      const readBtn = document.createElement('button');
      readBtn.className = 'hint-read-btn';
      readBtn.innerHTML = '🔊 朗讀答案';
      readBtn.onclick = (e) => {
        e.stopPropagation();
        // Strip any [--...--] markers for clean TTS
        const clean = answerText.replace(/\[--[^-]*--\]/g, '').replace(/[_\-]+/g, '').trim();
        AudioMgr.speak(clean);
        readBtn.innerHTML = '🔊 朗讀中…';
        readBtn.disabled = true;
        setTimeout(() => { readBtn.innerHTML = '🔊 再次朗讀'; readBtn.disabled = false; }, 2000);
      };
      hintBox.appendChild(Object.assign(document.createElement('div'), {
        className: 'hint-answer-label',
        textContent: '📋 參考答案'
      }));
      hintBox.appendChild(readBtn);
      const answerDiv = document.createElement('div');
      answerDiv.className = 'hint-answer-text';
      answerDiv.innerHTML = answerText.replace(/；/g, '；\n').replace(/\n/g, '<br>');
      hintBox.appendChild(answerDiv);
      hintWrap.appendChild(hintBox);

      area.appendChild(hintWrap);

    } else if (q.type === 'classify') {
      this.renderClassify(q, area);
    } else if (q.type === 'order') {
      this.renderOrder(q, area);
    } else if (q.type === 'match') {
      this.renderMatch(q, area);
    }
  },

  renderClassify(q, area) {
    const wrap = document.createElement('div');
    wrap.className = 'classify-wrap';

    // Pool
    const poolWrap = document.createElement('div');
    poolWrap.className = 'classify-items';
    poolWrap.innerHTML = '<h4>項目池</h4>';
    const pool = document.createElement('div');
    pool.className = 'classify-pool';
    pool.id = 'cPool';
    q.options.forEach(item => {
      const tag = document.createElement('div');
      tag.className = 'classify-tag';
      tag.textContent = item;
      tag.onclick = () => { this.classify_state._selected = item; tag.style.outline = '2px solid gold'; };
      pool.appendChild(tag);
    });
    poolWrap.appendChild(pool);

    // Bins
    const binsWrap = document.createElement('div');
    binsWrap.className = 'classify-bins';
    q.categories.forEach(cat => {
      this.classify_state[cat] = [];
      const bin = document.createElement('div');
      bin.className = 'classify-bin';
      bin.innerHTML = `<h4>${cat}</h4>`;
      const items = document.createElement('div');
      items.className = 'classify-bin-items';
      items.id = 'bin_' + cat;
      bin.appendChild(items);
      bin.onclick = () => {
        const sel = this.classify_state._selected;
        if (!sel) return;
        // Remove from pool display
        document.querySelectorAll('.classify-pool .classify-tag').forEach(t => {
          if (t.textContent === sel) { t.style.display = 'none'; t.style.outline = ''; }
        });
        // Remove from other bins
        q.categories.forEach(c => {
          this.classify_state[c] = this.classify_state[c].filter(x => x !== sel);
          const bi = document.getElementById('bin_' + c);
          if (bi) bi.querySelectorAll('.classify-tag').forEach(t => { if (t.textContent === sel) t.remove(); });
        });
        // Add to this bin
        this.classify_state[cat].push(sel);
        const t2 = document.createElement('div');
        t2.className = 'classify-tag';
        t2.textContent = sel;
        t2.title = '點擊取消';
        t2.onclick = () => {
          // Remove from bin state
          this.classify_state[cat] = this.classify_state[cat].filter(x => x !== t2.textContent);
          t2.remove();
          // Return to pool
          document.querySelectorAll('.classify-pool .classify-tag').forEach(pt => {
            if (pt.textContent === t2.textContent) { pt.style.display = ''; pt.style.outline = ''; }
          });
          this.classify_state._selected = null;
          this.currentUserAnswer = Object.assign({}, this.classify_state);
        };
        items.appendChild(t2);
        this.classify_state._selected = null;
        this.currentUserAnswer = Object.assign({}, this.classify_state);
      };
      binsWrap.appendChild(bin);
    });

    wrap.appendChild(poolWrap);
    wrap.appendChild(binsWrap);
    area.appendChild(wrap);
  },

  startTimer(seconds) {
    this.totalTime = seconds;
    this.timeLeft = seconds;
    clearInterval(this.timer);
    document.getElementById('timerTxt').textContent = seconds + 's';
    document.getElementById('timerBarFill').style.width = '100%';
    document.getElementById('timerBarFill').style.background = 'linear-gradient(90deg,#00e5e5,#6b21a8)';

    this.timer = setInterval(() => {
      this.timeLeft--;
      const pct = (this.timeLeft / this.totalTime * 100);
      document.getElementById('timerTxt').textContent = this.timeLeft + 's';
      document.getElementById('timerBarFill').style.width = pct + '%';
      if (pct < 30) document.getElementById('timerBarFill').style.background = 'linear-gradient(90deg,#ef4444,#ff7a00)';
      if (this.timeLeft <= 0) { clearInterval(this.timer); this.submit(); }
    }, 1000);
  },

  stopTimer() { clearInterval(this.timer); document.getElementById('timerTxt').textContent = '—'; },

  renderMatch(q, area) {
    // currentUserAnswer = array of selected option keys, one per left item (null if unset)
    this.currentUserAnswer = new Array(q.left.length).fill(null);
    const wrap = document.createElement('div');
    wrap.className = 'match-wrap';

    // Options legend at top
    const legend = document.createElement('div');
    legend.className = 'match-legend';
    q.options.forEach(opt => {
      const row = document.createElement('div');
      row.className = 'match-legend-row';
      row.textContent = opt;
      legend.appendChild(row);
    });
    wrap.appendChild(legend);

    // One row per left item
    q.left.forEach((item, idx) => {
      const row = document.createElement('div');
      row.className = 'match-row';

      const label = document.createElement('div');
      label.className = 'match-left-label';
      label.textContent = item;
      row.appendChild(label);

      const btns = document.createElement('div');
      btns.className = 'match-btn-group';
      // Collect unique first letters from options as keys
      const keys = q.options.map(o => o[0]);
      keys.forEach(key => {
        const btn = document.createElement('button');
        btn.className = 'match-key-btn';
        btn.textContent = key;
        btn.dataset.key = key;
        btn.onclick = () => {
          btns.querySelectorAll('.match-key-btn').forEach(b => b.classList.remove('selected'));
          btn.classList.add('selected');
          this.currentUserAnswer[idx] = key;
          AudioMgr.click();
        };
        btns.appendChild(btn);
      });
      row.appendChild(btns);
      wrap.appendChild(row);
    });

    area.appendChild(wrap);
  },

  renderOrder(q, area) {
    this.currentUserAnswer = [];
    const wrap = document.createElement('div');
    wrap.className = 'order-wrap';

    // Sequence slots row
    const seqRow = document.createElement('div');
    seqRow.className = 'order-seq-row';
    seqRow.id = 'orderSeqRow';
    q.items.forEach((_, i) => {
      if (i > 0) {
        const arrow = document.createElement('span');
        arrow.className = 'order-arrow';
        arrow.textContent = '→';
        seqRow.appendChild(arrow);
      }
      const slot = document.createElement('div');
      slot.className = 'order-slot';
      slot.dataset.idx = i;
      slot.textContent = ' ';
      slot.onclick = () => {
        // Return item to pool
        const key = slot.dataset.key;
        if (!key) return;
        // Remove from answer
        const pos = this.currentUserAnswer.indexOf(key);
        if (pos !== -1) this.currentUserAnswer.splice(pos, 1);
        // Re-enable pool card
        const card = area.querySelector(`.order-card[data-key="${key}"]`);
        if (card) { card.classList.remove('used'); card.disabled = false; }
        // Clear slot
        slot.textContent = ' ';
        delete slot.dataset.key;
        slot.classList.remove('filled');
        AudioMgr.click();
      };
      seqRow.appendChild(slot);
    });
    wrap.appendChild(seqRow);

    // Item cards pool
    const pool = document.createElement('div');
    pool.className = 'order-pool';
    q.items.forEach(item => {
      const card = document.createElement('button');
      card.className = 'order-card';
      card.dataset.key = item.key;
      card.innerHTML = `<span class="order-key">${item.key}</span><span class="order-txt">${item.text}</span>`;
      card.onclick = () => {
        if (card.classList.contains('used')) return;
        // Find next empty slot
        const slots = seqRow.querySelectorAll('.order-slot');
        let placed = false;
        slots.forEach(slot => {
          if (!placed && !slot.dataset.key) {
            slot.textContent = item.key;
            slot.dataset.key = item.key;
            slot.classList.add('filled');
            card.classList.add('used');
            card.disabled = true;
            this.currentUserAnswer.push(item.key);
            placed = true;
          }
        });
        AudioMgr.click();
      };
      pool.appendChild(card);
    });
    wrap.appendChild(pool);

    const hint = document.createElement('div');
    hint.style.cssText = 'font-size:12px;color:rgba(212,175,55,0.7);margin-top:8px;';
    hint.textContent = '💡 點選項目加入排列，點已填格子可取消';
    wrap.appendChild(hint);

    area.appendChild(wrap);
  },

  submit() {
    if (this.submitted) return;
    this.submitted = true;
    this.stopTimer();
    const q = this.questions[this.idx];
    const isCorrect = this.checkAnswer(q, this.currentUserAnswer);
    this.answers.push({ qid: q.id, correct: isCorrect, userAnswer: this.currentUserAnswer });

    const usedHint = !!this.hintUsed;
    if (isCorrect) {
      this.sessionCorrect++;
      if (!usedHint) {
        this.earnedXP += 10;
        this.earnedCoins += 5;
      }
      STATE.stats.currentStreak++;
      STATE.stats.maxStreak = Math.max(STATE.stats.maxStreak, STATE.stats.currentStreak);
      AudioMgr.correct();
      Particles.burst(window.innerWidth/2, 200, '#4ade80');
    } else {
      STATE.stats.currentStreak = 0;
      AudioMgr.wrong();
      // Add to wrong bank
      const existing = STATE.wrongBank.find(w => w.qid === q.id);
      if (!existing) STATE.wrongBank.push({ qid: q.id, module: q.module, addedAt: Date.now(), retries: 0 });
    }

    STATE.stats.totalAnswered++;
    if (isCorrect) STATE.stats.totalCorrect++;
    if (!STATE.stats.byModule[q.module]) STATE.stats.byModule[q.module] = {answered:0,correct:0};
    STATE.stats.byModule[q.module].answered++;
    if (isCorrect) STATE.stats.byModule[q.module].correct++;
    STATE.stats.today.answered++;
    if (isCorrect) STATE.stats.today.correct++;

    this.showFeedback(q, isCorrect);
    document.getElementById('quizNavRow').style.display = 'none';
    document.getElementById('feedbackArea').style.display = 'flex';

    if (isCorrect && !usedHint) {
      Rewards.addXP(10);
      Rewards.addCoins(5);
    }
    Rewards.checkBadges();
    Store.save();
    App.updateDashToday();
  },

  checkAnswer(q, userAns) {
    if (userAns === null || userAns === undefined || userAns === '') return false;
    if (q.type === 'mc') {
      if (q.multi) {
        if (!Array.isArray(userAns) || userAns.length === 0) return false;
        const got = [...userAns].sort((a,b)=>a-b);
        const exp = [...q.answer].sort((a,b)=>a-b);
        return JSON.stringify(got) === JSON.stringify(exp);
      }
      return parseInt(userAns) === q.answer;
    }
    if (q.type === 'classify') {
      if (typeof userAns !== 'object') return false;
      let allCorrect = true;
      q.categories.forEach(cat => {
        const expected = q.answer[cat] || [];
        const got = userAns[cat] || [];
        if (expected.length !== got.length) allCorrect = false;
        expected.forEach(e => { if (!got.includes(e)) allCorrect = false; });
      });
      return allCorrect;
    }
    if (q.type === 'order') {
      if (!Array.isArray(userAns) || userAns.length !== q.answer.length) return false;
      return JSON.stringify(userAns) === JSON.stringify(q.answer);
    }
    if (q.type === 'match') {
      if (!Array.isArray(userAns) || userAns.some(v => v === null)) return false;
      return JSON.stringify(userAns) === JSON.stringify(q.answer);
    }
    // Text-based: check if contains key keywords
    if (typeof userAns === 'string' && userAns.length > 3) return true; // Give credit for effort
    return false;
  },

  showFeedback(q, isCorrect) {
    const res = document.getElementById('feedbackResult');
    const usedHint = !!this.hintUsed;
    res.className = 'feedback-result ' + (isCorrect ? 'correct' : 'wrong');
    if (isCorrect) {
      if (usedHint) {
        res.innerHTML = '✅ 答對了！（已用提示，不計分）';
      } else {
        res.textContent = '✅ 答對了！太棒了！+10 XP +5 🪙';
      }
    } else {
      let correctStr = '';
      if (q.type === 'mc') {
        const letters = ['A','B','C','D'];
        if (q.multi) {
          correctStr = '正確答案：' + q.answer.map(i => letters[i]).join('、');
        } else {
          correctStr = '正確答案：' + letters[q.answer] + '. ' + q.options[q.answer];
        }
      }
      res.textContent = '❌ 答錯了！' + correctStr;
      // Highlight correct MC option
      if (q.type === 'mc') {
        const opts = document.querySelectorAll('.mc-option');
        const correctSet = q.multi ? new Set(q.answer) : new Set([q.answer]);
        opts.forEach((o,i) => {
          if (correctSet.has(i)) o.classList.add('correct');
          else if (o.classList.contains('selected')) o.classList.add('wrong');
        });
      }
      // Show correct match for matching questions
      if (q.type === 'match') {
        const matchHint = document.createElement('div');
        matchHint.style.cssText = 'margin-top:8px;font-size:13px;color:#ffd700;line-height:1.8;';
        matchHint.textContent = '正確答案：' + q.left.map((l,i) => l.replace(/^\d+\.\s*/,'') + ' → ' + q.answer[i]).join('　');
        res.appendChild(matchHint);
        // Colour match rows
        const rows = document.querySelectorAll('.match-row');
        rows.forEach((row, i) => {
          const chosen = (this.currentUserAnswer || [])[i];
          row.style.borderLeft = chosen === q.answer[i] ? '3px solid #4ade80' : '3px solid #ef4444';
        });
      }
      // Show correct order for ordering questions
      if (q.type === 'order') {
        const orderHint = document.createElement('div');
        orderHint.style.cssText = 'margin-top:8px;font-size:13px;color:#ffd700;';
        orderHint.textContent = '正確順序：' + q.answer.join(' → ');
        res.appendChild(orderHint);
        // Colour the slots
        const slots = document.querySelectorAll('.order-slot');
        slots.forEach((slot, i) => {
          slot.style.borderColor = slot.dataset.key === q.answer[i] ? '#4ade80' : '#ef4444';
          slot.style.color = slot.dataset.key === q.answer[i] ? '#4ade80' : '#ef4444';
        });
      }
    }
    document.getElementById('teacherBody').textContent = q.explanation || '（沒有詳細解釋）';
  },

  skip() {
    if (this.submitted) return;
    this.currentUserAnswer = null;
    this.submit();
  },

  next() {
    this.idx++;
    if (this.idx >= this.questions.length) this.finish();
    else this.renderQuestion();
  },

  finish() {
    clearInterval(this.timer);
    const total = this.questions.length;
    const correct = this.sessionCorrect;
    const pct = total > 0 ? Math.round(correct / total * 100) : 0;

    if (pct === 100 && total > 0) STATE.stats.lastPerfect = true;
    else STATE.stats.lastPerfect = false;

    // Daily log entry
    const elapsed = this.sessionStartTime ? Math.round((Date.now() - this.sessionStartTime) / 1000) : 0;
    const logEntry = {
      date: new Date().toISOString().slice(0,10),
      ts: Date.now(),
      module: STATE.currentModule || '—',
      qtype: STATE.currentQType || '—',
      total,
      correct,
      pct,
      secs: elapsed > 0 ? elapsed : 0
    };
    if (!STATE.dailyLog) STATE.dailyLog = [];
    STATE.dailyLog.push(logEntry);
    // Keep only last 90 days
    const cutoff = Date.now() - 90 * 86400000;
    STATE.dailyLog = STATE.dailyLog.filter(e => e.ts >= cutoff);

    Rewards.checkBadges();
    Store.save();

    // Show results
    document.getElementById('resultsTitle').textContent = pct >= 90 ? '🏆 優秀！' : pct >= 70 ? '🌟 良好！' : pct >= 50 ? '📚 繼續努力！' : '💪 加油！';
    document.getElementById('resultsPct').textContent = pct;
    document.getElementById('resultsGrade').textContent = pct >= 90 ? '霍格華茲頂尖學生！' : pct >= 70 ? '知識魔法師！' : pct >= 50 ? '魔法學徒繼續努力！' : '初級見習巫師，多多練習吧！';
    document.getElementById('rCorrect').textContent = correct;
    document.getElementById('rWrong').textContent = total - correct;
    document.getElementById('rXP').textContent = '+' + this.earnedXP;
    document.getElementById('rCoins').textContent = '+' + this.earnedCoins;

    if (pct === 100) Particles.burst(window.innerWidth/2, window.innerHeight/3, '#ffd700');
    App.showScreen('screen-results');
  }
};

// ============ WRONG CENTER ============
const WrongCenter = {
  render() {
    const filter = document.getElementById('wrongFilter').value;
    let items = STATE.wrongBank;
    if (filter !== 'all') items = items.filter(w => w.module === filter);

    document.getElementById('wrongCount').textContent = items.length + ' 題';
    const list = document.getElementById('wrongList');
    list.innerHTML = '';

    if (items.length === 0) {
      list.innerHTML = '<div class="empty-msg">🎉 沒有錯題！繼續保持！</div>';
      return;
    }

    items.forEach(w => {
      const q = this.findQ(w.qid);
      if (!q) return;
      const div = document.createElement('div');
      div.className = 'wrong-item';
      div.innerHTML = `
        <div class="wrong-item-q">${q.question.substring(0,100)}${q.question.length>100?'⋯':''}</div>
        <div class="wrong-item-meta">
          <span>課題：${q.module} ${App.moduleName(q.module)}</span>
          <span>題型：${App.typeName(q.type)}</span>
          <span>重做：${w.retries}次</span>
        </div>
        <div class="wrong-item-btns">
          <button class="pixel-btn small gold" onclick="WrongCenter.retryOne('${w.qid}')">重做這題</button>
          <button class="pixel-btn small grey" onclick="WrongCenter.remove('${w.qid}')">移除</button>
        </div>`;
      list.appendChild(div);
    });
  },

  findQ(qid) {
    return [...QUESTIONS, ...STATE.customQuestions, ...(PASSAGES.flatMap(p => p.questions.map(q => ({...q, module: p.module}))))]
      .find(q => q.id === qid);
  },

  retryOne(qid) {
    const q = this.findQ(qid);
    if (!q) return;
    const w = STATE.wrongBank.find(x => x.qid === qid);
    if (w) w.retries++;
    QuizEngine.start([q]);
  },

  retryAll() {
    const filter = document.getElementById('wrongFilter').value;
    let items = STATE.wrongBank;
    if (filter !== 'all') items = items.filter(w => w.module === filter);
    if (items.length === 0) { App.toast('沒有錯題！'); return; }
    const qs = items.map(w => this.findQ(w.qid)).filter(Boolean);
    STATE.currentModule = 'all';
    STATE.currentQType = 'wrong';
    QuizEngine.start(qs);
  },

  remove(qid) {
    STATE.wrongBank = STATE.wrongBank.filter(w => w.qid !== qid);
    Store.save(); this.render();
  },

  clearAll() {
    if (!confirm('確定清除所有錯題？')) return;
    const filter = document.getElementById('wrongFilter').value;
    if (filter === 'all') STATE.wrongBank = [];
    else STATE.wrongBank = STATE.wrongBank.filter(w => w.module !== filter);
    Store.save(); this.render();
  }
};

// ============ PARENT MODE ============
const ParentMode = {
  tab(name) {
    document.querySelectorAll('.ptab').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.ptab-content').forEach(c => c.style.display = 'none');
    document.getElementById('ptab-' + name).classList.add('active');
    document.getElementById('ptabContent-' + name).style.display = 'block';
    if (name === 'stats') this.renderStats();
    if (name === 'manage') this.renderManage();
  },

  renderStats() {
    document.getElementById('pStudentName').textContent = STATE.playerName || '（未設定）';
    document.getElementById('pTotalQ').textContent = STATE.stats.totalAnswered;
    const acc = STATE.stats.totalAnswered > 0 ? Math.round(STATE.stats.totalCorrect / STATE.stats.totalAnswered * 100) + '%' : '—';
    document.getElementById('pAcc').textContent = acc;
    document.getElementById('pLvl').textContent = STATE.level;
    document.getElementById('pLoginStreak').textContent = STATE.loginStreak;

    const modEl = document.getElementById('pModStats');
    modEl.innerHTML = '';
    ['6.1','6.2','6.3','6.4','6.5','6.6'].forEach(mod => {
      const s = STATE.stats.byModule[mod] || {answered:0,correct:0};
      const p = s.answered > 0 ? Math.round(s.correct/s.answered*100) : 0;
      modEl.innerHTML += `<div class="p-mod-row">
        <div class="p-mod-name">${mod} ${App.moduleName(mod)}</div>
        <div class="p-mod-bar-wrap"><div class="p-mod-bar" style="width:${p}%"></div></div>
        <div class="p-mod-pct">${p}%</div>
      </div>`;
    });

    const weak = ['6.1','6.2','6.3','6.4','6.5','6.6'].filter(mod => {
      const s = STATE.stats.byModule[mod];
      return s && s.answered >= 3 && s.correct/s.answered < 0.6;
    }).map(mod => mod + ' ' + App.moduleName(mod));
    document.getElementById('pWeakness').innerHTML = weak.length
      ? weak.map(w => `<span class="weakness-tag">⚠️ ${w}</span>`).join('')
      : '<span style="color:rgba(245,230,200,0.5)">目前沒有明顯弱項</span>';
  },

  updateForm() {
    const type = document.getElementById('nqType').value;
    document.getElementById('nqMcSection').style.display = type === 'mc' ? 'block' : 'none';
    document.getElementById('nqTextSection').style.display = type !== 'mc' ? 'block' : 'none';
  },

  saveQ() {
    const type = document.getElementById('nqType').value;
    const text = document.getElementById('nqText').value.trim();
    if (!text) { App.toast('請輸入題目！'); return; }

    const q = {
      id: 'custom_' + Date.now(),
      module: document.getElementById('nqModule').value,
      type,
      question: text,
      explanation: document.getElementById('nqExplain').value.trim(),
      isCustom: true
    };

    if (type === 'mc') {
      q.options = [
        document.getElementById('nqA').value,
        document.getElementById('nqB').value,
        document.getElementById('nqC').value,
        document.getElementById('nqD').value
      ];
      q.answer = parseInt(document.getElementById('nqMcAns').value);
    } else {
      q.answer = document.getElementById('nqTextAns').value.trim();
    }

    STATE.customQuestions.push(q);
    Store.save();
    App.toast('✅ 題目已儲存！');
    document.getElementById('nqText').value = '';
    document.getElementById('nqExplain').value = '';
  },

  renderManage() {
    const filter = document.getElementById('manageFilter').value;
    let qs = [...QUESTIONS, ...STATE.customQuestions];
    if (filter === 'custom') qs = STATE.customQuestions;
    else if (filter !== 'all') qs = qs.filter(q => q.module === filter);

    const list = document.getElementById('manageList');
    list.innerHTML = qs.length === 0 ? '<div class="empty-msg">沒有題目</div>' : '';
    qs.forEach(q => {
      const div = document.createElement('div');
      div.className = 'manage-item';
      div.innerHTML = `
        <div class="manage-item-q">${q.question.substring(0,80)}${q.question.length>80?'⋯':''}</div>
        <div class="manage-item-meta">${q.module} · ${App.typeName(q.type)}${q.isCustom?' · 自訂':''}</div>
        <div class="manage-item-btns">
          ${q.isCustom ? `<button class="pixel-btn small gold" onclick="ParentMode.editQ('${q.id}')">編輯</button>` : ''}
          ${q.isCustom ? `<button class="pixel-btn small red" onclick="ParentMode.deleteQ('${q.id}')">刪除</button>` : ''}
        </div>`;
      list.appendChild(div);
    });
  },

  editQ(id) {
    const q = STATE.customQuestions.find(x => x.id === id);
    if (!q) return;
    const form = document.getElementById('editQForm');
    form.innerHTML = `
      <div class="form-row"><label>題目：</label><textarea id="eq_text" rows="3" class="pixel-input">${q.question}</textarea></div>
      <div class="form-row"><label>答案：</label><textarea id="eq_ans" rows="2" class="pixel-input">${typeof q.answer==='number'?['A','B','C','D'][q.answer]:q.answer}</textarea></div>
      <div class="form-row"><label>解釋：</label><textarea id="eq_exp" rows="2" class="pixel-input">${q.explanation||''}</textarea></div>`;
    form.dataset.id = id;
    App.openModal('modal-edit-q');
  },

  saveEdit() {
    const id = document.getElementById('editQForm').dataset.id;
    const q = STATE.customQuestions.find(x => x.id === id);
    if (!q) return;
    q.question = document.getElementById('eq_text').value;
    q.explanation = document.getElementById('eq_exp').value;
    Store.save();
    App.closeModal('modal-edit-q');
    this.renderManage();
    App.toast('✅ 已更新題目！');
  },

  deleteQ(id) {
    if (!confirm('確定刪除這道題目？')) return;
    STATE.customQuestions = STATE.customQuestions.filter(q => q.id !== id);
    Store.save();
    this.renderManage();
    App.toast('🗑️ 已刪除題目。');
  },

  drop(e) {
    e.preventDefault();
    document.getElementById('uploadDrop').classList.remove('dragover');
    const files = e.dataTransfer.files;
    if (files.length) this.handleFiles(files);
  },

  handleFiles(files) {
    Array.from(files).forEach(file => this.processFile(file));
  },

  processFile(file) {
    const prog = document.getElementById('uploadProgress');
    const status = document.getElementById('upStatus');
    const fill = document.getElementById('upBarFill');
    prog.style.display = 'block';
    status.textContent = '讀取檔案：' + file.name;
    fill.style.width = '20%';

    if (file.type.startsWith('image/')) {
      this.ocrImage(file, fill, status, prog);
    } else if (file.type === 'application/pdf') {
      status.textContent = '注意：PDF需要在瀏覽器中打開。請複製文字後使用「手動新增」功能。';
      fill.style.width = '100%';
      setTimeout(() => { prog.style.display = 'none'; }, 3000);
    } else {
      // Try reading as text (for .txt or simple files)
      const reader = new FileReader();
      reader.onload = e => {
        fill.style.width = '100%';
        status.textContent = '完成！';
        const extracted = document.getElementById('extractedArea');
        extracted.style.display = 'block';
        document.getElementById('extractedTA').value = e.target.result.substring(0, 2000);
        setTimeout(() => { prog.style.display = 'none'; }, 1000);
      };
      reader.readAsText(file, 'UTF-8');
    }
  },

  ocrImage(file, fill, status, prog) {
    status.textContent = '正在識別圖片文字⋯ （需要網絡連接）';
    fill.style.width = '40%';

    // Try Tesseract if available
    if (typeof Tesseract !== 'undefined') {
      Tesseract.recognize(file, 'chi_tra+eng', {
        logger: m => {
          if (m.status === 'recognizing text') fill.style.width = (40 + m.progress * 50) + '%';
        }
      }).then(({ data: { text } }) => {
        fill.style.width = '100%';
        status.textContent = '識別完成！';
        document.getElementById('extractedArea').style.display = 'block';
        document.getElementById('extractedTA').value = text;
        setTimeout(() => { prog.style.display = 'none'; }, 1000);
      }).catch(() => {
        status.textContent = '識別失敗，請手動輸入題目。';
        setTimeout(() => { prog.style.display = 'none'; }, 2000);
      });
    } else {
      // Load Tesseract from CDN
      const script = document.createElement('script');
      script.src = 'https://unpkg.com/tesseract.js@4/dist/tesseract.min.js';
      script.onload = () => this.ocrImage(file, fill, status, prog);
      script.onerror = () => {
        status.textContent = '無法載入OCR工具，請手動輸入題目。';
        setTimeout(() => { prog.style.display = 'none'; }, 2000);
      };
      document.head.appendChild(script);
    }
  },

  addAsQuestion() {
    const text = document.getElementById('extractedTA').value.trim();
    if (!text) return;
    document.getElementById('nqText').value = text;
    this.tab('upload');
    App.toast('已複製到「手動新增」區域，請完成其餘資料。');
  }
};

// ============ REPORTS ============
const Report = {
  render() {
    document.getElementById('repTotal').textContent = STATE.stats.totalAnswered;
    document.getElementById('repCorrect').textContent = STATE.stats.totalCorrect;
    const acc = STATE.stats.totalAnswered > 0 ? Math.round(STATE.stats.totalCorrect / STATE.stats.totalAnswered * 100) + '%' : '—';
    document.getElementById('repAcc').textContent = acc;
    document.getElementById('repMaxStreak').textContent = STATE.stats.maxStreak;

    // By module
    const modEl = document.getElementById('repModules');
    modEl.innerHTML = '';
    ['6.1','6.2','6.3','6.4','6.5','6.6'].forEach(mod => {
      const s = STATE.stats.byModule[mod] || {answered:0,correct:0};
      const p = s.answered > 0 ? Math.round(s.correct/s.answered*100) : 0;
      modEl.innerHTML += `<div class="mod-report-row">
        <div class="mod-report-name">${mod} ${App.moduleName(mod)}</div>
        <div class="mod-report-bar-wrap"><div class="mod-report-bar" style="width:${p}%"></div></div>
        <div class="mod-report-pct">${s.answered>0?p+'%':'—'}</div>
      </div>`;
    });

    // Weakness
    const weak = ['6.1','6.2','6.3','6.4','6.5','6.6'].filter(mod => {
      const s = STATE.stats.byModule[mod];
      return s && s.answered >= 3 && s.correct/s.answered < 0.6;
    });
    const weakEl = document.getElementById('repWeakness');
    weakEl.innerHTML = weak.length
      ? weak.map(m => `<span class="weakness-tag">⚠️ ${m} ${App.moduleName(m)}</span>`).join('')
      : '<p style="color:rgba(245,230,200,0.5)">目前沒有明顯弱項，繼續保持！</p>';

    // Badges
    const badgeEl = document.getElementById('repBadges');
    badgeEl.innerHTML = '';
    BADGES.forEach(b => {
      const unlocked = STATE.badges.includes(b.id);
      badgeEl.innerHTML += `<div class="badge-item${unlocked?'':' locked'}" title="${b.desc}">
        <div class="b-icon">${b.icon}</div>
        <div class="b-name">${b.name}</div>
      </div>`;
    });

    // Daily log — last 14 days
    const logEl = document.getElementById('repDailyLog');
    if (logEl) {
      const log = (STATE.dailyLog || []).slice().reverse();
      if (!log.length) {
        logEl.innerHTML = '<p style="color:rgba(245,230,200,0.5)">尚未有紀錄，完成測驗後將自動記錄。</p>';
      } else {
        // Group by date
        const byDate = {};
        log.forEach(e => {
          if (!byDate[e.date]) byDate[e.date] = [];
          byDate[e.date].push(e);
        });
        const cutDate = new Date(Date.now() - 14*86400000).toISOString().slice(0,10);
        let html = '';
        Object.keys(byDate).filter(d => d >= cutDate).sort((a,b) => b.localeCompare(a)).forEach(date => {
          const entries = byDate[date];
          const dayTotal = entries.reduce((s,e)=>s+e.total,0);
          const dayCorrect = entries.reduce((s,e)=>s+e.correct,0);
          const dayPct = dayTotal>0 ? Math.round(dayCorrect/dayTotal*100) : 0;
          html += `<div class="dlog-day">
            <div class="dlog-date">📅 ${date} &nbsp;<span class="dlog-day-summary">${entries.length}次練習 · ${dayTotal}題 · 正確率${dayPct}%</span></div>`;
          entries.forEach(e => {
            const mins = Math.floor(e.secs/60), secs = e.secs%60;
            const timeStr = e.secs>0 ? `${mins}分${secs}秒` : '—';
            const col = e.pct>=80?'#4ade80':e.pct>=60?'#facc15':'#f87171';
            html += `<div class="dlog-row">
              <span class="dlog-mod">${e.module}</span>
              <span class="dlog-type">${App.typeName(e.qtype)}</span>
              <span class="dlog-score" style="color:${col}">${e.correct}/${e.total} (${e.pct}%)</span>
              <span class="dlog-time">⏱ ${timeStr}</span>
            </div>`;
          });
          html += '</div>';
        });
        logEl.innerHTML = html || '<p style="color:rgba(245,230,200,0.5)">最近14日沒有紀錄。</p>';
      }
    }
  }
};

// ============ MAIN APP ============
const App = {
  lastQuizModule: null, lastQuizType: null,

  init() {
    Store.load();
    Particles.init();
    AudioMgr.init();

    // Voices need time to load
    if (window.speechSynthesis) window.speechSynthesis.getVoices();

    if (STATE.playerName) {
      this.checkDailyLogin();
    } else {
      this.showScreen('screen-welcome');
    }

    // Music button state
    document.getElementById('musicToggle').textContent = STATE.settings.musicOn ? '🎵' : '🔇';
    AudioMgr.musicOn = STATE.settings.musicOn;
    if (STATE.settings.musicOn) setTimeout(() => AudioMgr.startBgMusic(), 500);
  },

  startGame() {
    const name = document.getElementById('playerNameInput').value.trim();
    if (!name) { this.toast('請輸入你的名字！'); return; }
    STATE.playerName = name;
    Store.save();
    AudioMgr.click();
    this.checkDailyLogin();
  },

  checkDailyLogin() {
    const today = new Date().toDateString();
    if (STATE.lastLoginDate !== today) {
      const yesterday = new Date(Date.now() - 86400000).toDateString();
      if (STATE.lastLoginDate === yesterday) STATE.loginStreak++;
      else if (!STATE.lastLoginDate) STATE.loginStreak = 1;
      else STATE.loginStreak = 1;
      STATE.lastLoginDate = today;
      STATE.stats.today = { answered: 0, correct: 0, xp: 0, coins: 0, date: today };
      Store.save();
      this.showDailyReward();
    } else {
      this.goToDashboard();
    }
  },

  showDailyReward() {
    document.getElementById('streakCount').textContent = STATE.loginStreak;
    const baseXP = 10 + STATE.loginStreak * 5;
    const baseCoins = 5 + STATE.loginStreak * 2;
    document.getElementById('rewardItems').innerHTML = `
      <div class="reward-item"><div class="reward-item-icon">⭐</div><div class="reward-item-val">+${baseXP}</div><div class="reward-item-lbl">XP</div></div>
      <div class="reward-item"><div class="reward-item-icon">🪙</div><div class="reward-item-val">+${baseCoins}</div><div class="reward-item-lbl">金幣</div></div>
      ${STATE.loginStreak >= 7 ? '<div class="reward-item"><div class="reward-item-icon">🎖️</div><div class="reward-item-val">勳章</div><div class="reward-item-lbl">七日學霸</div></div>' : ''}`;
    this._dailyXP = baseXP; this._dailyCoins = baseCoins;
    this.showScreen('screen-daily-reward');
  },

  claimReward() {
    Rewards.addXP(this._dailyXP || 10);
    Rewards.addCoins(this._dailyCoins || 5);
    Rewards.checkBadges();
    Store.save();
    Particles.burst(window.innerWidth/2, window.innerHeight/2, '#d4af37');
    AudioMgr.correct();
    this.goToDashboard();
  },

  goToDashboard() {
    this.showScreen('screen-dashboard');
    document.getElementById('audioControls').style.display = 'flex';
    this.updateStatsBar();
    this.updateDashToday();
    this.updateModuleProgress();
  },

  updateStatsBar() {
    document.getElementById('dashName').textContent = STATE.playerName;
    document.getElementById('dashLevel').textContent = STATE.level;
    document.getElementById('dashCoins').textContent = STATE.coins;
    document.getElementById('dashStreak').textContent = STATE.loginStreak;
    const pct = (STATE.xp / XP_PER_LEVEL * 100).toFixed(0);
    document.getElementById('dashXpBar').style.width = pct + '%';
    document.getElementById('dashXpText').textContent = STATE.xp + '/' + XP_PER_LEVEL;
  },

  updateDashToday() {
    document.getElementById('todayQ').textContent = STATE.stats.today.answered || 0;
    document.getElementById('todayC').textContent = STATE.stats.today.correct || 0;
    document.getElementById('todayXP').textContent = STATE.stats.today.xp || 0;
    document.getElementById('todayCoinsEarned').textContent = STATE.stats.today.coins || 0;
  },

  updateModuleProgress() {
    ['6.1','6.2','6.3','6.4','6.5','6.6'].forEach(mod => {
      const s = STATE.stats.byModule[mod];
      const p = s && s.answered > 0 ? Math.round(s.correct/s.answered*100) : 0;
      const el = document.getElementById('mprog-' + mod);
      const tx = document.getElementById('mprog-txt-' + mod);
      if (el) el.style.width = p + '%';
      if (tx) tx.textContent = s ? p + '%' : '0%';
    });
  },

  selectModule(mod) {
    STATE.currentModule = mod;
    document.getElementById('qtypeModTitle').textContent = mod + ' ' + this.moduleName(mod);
    AudioMgr.click();
    this.showScreen('screen-question-types');
  },

  startQuiz(type) {
    STATE.currentQType = type;
    this.lastQuizModule = STATE.currentModule;
    this.lastQuizType = type;
    AudioMgr.click();

    let qs = [];
    const allQ = [...QUESTIONS, ...STATE.customQuestions];

    if (type === 'reading') {
      const relevant = PASSAGES.filter(p => STATE.currentModule === 'all' || p.module === STATE.currentModule);
      if (relevant.length === 0) { this.toast('此課題暫無閱讀理解題目'); return; }
      const p = relevant[Math.floor(Math.random() * relevant.length)];
      qs = p.questions.map(q => ({
        ...q, passage: p.text, module: p.module
      }));
    } else if (type === 'mixed') {
      qs = allQ.filter(q => STATE.currentModule === 'all' || q.module === STATE.currentModule);
      qs = this.shuffle(qs).slice(0, 12);
    } else {
      qs = allQ.filter(q =>
        (STATE.currentModule === 'all' || q.module === STATE.currentModule) && q.type === type
      );
      qs = this.shuffle(qs).slice(0, 10);
    }

    if (qs.length === 0) { this.toast('此課題暫無此類型題目，請選擇其他題型！'); return; }
    QuizEngine.start(qs);
  },

  retryQuiz() {
    if (this.lastQuizModule && this.lastQuizType) {
      STATE.currentModule = this.lastQuizModule;
      this.startQuiz(this.lastQuizType);
    } else {
      this.showScreen('screen-modules');
    }
  },

  exitQuiz() {
    if (confirm('確定退出測驗？進度不會保存。')) {
      clearInterval(QuizEngine.timer);
      this.showScreen('screen-dashboard');
    }
  },

  goWrongReview() {
    this.showScreen('screen-wrong-review');
    WrongCenter.render();
  },

  showBadgesModal() {
    const grid = document.getElementById('badgeGridModal');
    grid.innerHTML = '';
    BADGES.forEach(b => {
      const unlocked = STATE.badges.includes(b.id);
      grid.innerHTML += `<div class="badge-item${unlocked?'':' locked'}" title="${b.desc}">
        <div class="b-icon">${b.icon}</div>
        <div class="b-name">${b.name}</div>
      </div>`;
    });
    this.openModal('modal-badges');
  },

  showParentLogin() { this.openModal('modal-parent-login'); },

  verifyParent() {
    const pw = document.getElementById('parentPw').value;
    if (pw === '1234') {
      STATE.parentUnlocked = true;
      this.closeModal('modal-parent-login');
      document.getElementById('parentPw').value = '';
      ParentMode.tab('stats');
      this.showScreen('screen-parent');
    } else {
      this.toast('密碼錯誤！'); AudioMgr.wrong();
    }
  },

  parentLogout() {
    STATE.parentUnlocked = false;
    this.showScreen('screen-dashboard');
  },

  showScreen(id) {
    document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
    document.getElementById(id).classList.add('active');
    AudioMgr.click();
    if (id === 'screen-wrong-review') WrongCenter.render();
    if (id === 'screen-report') Report.render();
    if (id === 'screen-modules') this.updateModuleProgress();
    window.scrollTo(0,0);
  },

  openModal(id) { document.getElementById(id).style.display = 'flex'; },
  closeModal(id) { document.getElementById(id).style.display = 'none'; },

  toast(msg) {
    const t = document.getElementById('toast');
    t.textContent = msg;
    t.classList.add('show');
    setTimeout(() => t.classList.remove('show'), 2500);
  },

  moduleName(mod) {
    const names = {'6.1':'處變不驚','6.2':'科技天地','6.3':'中國的變遷','6.4':'香港特別行政區','6.5':'生物世界','6.6':'放眼世界'};
    return names[mod] || mod;
  },

  typeName(type) {
    const names = {mc:'選擇題',fill:'填充題',short:'簡答題',analysis:'分析題',classify:'分類題',scenario:'生活情景題',order:'排序題',match:'配對題',reading:'閱讀理解',mixed:'混合',wrong:'錯題重溫'};
    return names[type] || type;
  },

  shuffle(arr) {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  }
};

// ============ INIT ============
document.addEventListener('DOMContentLoaded', () => {
  App.init();

  // Prevent accidental back navigation
  window.addEventListener('popstate', e => e.preventDefault());

  // Keyboard shortcuts
  document.addEventListener('keydown', e => {
    if (e.key === 'Enter') {
      const submitBtn = document.getElementById('submitBtn');
      if (submitBtn && document.getElementById('screen-quiz').classList.contains('active')) {
        QuizEngine.submit();
      }
    }
    // MC quick select 1-4
    if (['1','2','3','4'].includes(e.key) && document.getElementById('screen-quiz').classList.contains('active')) {
      const opts = document.querySelectorAll('.mc-option');
      const idx = parseInt(e.key) - 1;
      if (opts[idx]) opts[idx].click();
    }
  });

  // Speech voices ready
  if (window.speechSynthesis) {
    window.speechSynthesis.onvoiceschanged = () => window.speechSynthesis.getVoices();
  }
});
